import type { MemoryScope, SearchScope, SearchSourceRef } from '@my-pi-harness/protocol';

export interface SearchQualitySource {
  /** Complete SearchSourceRef ID, including the memory: or message: prefix. */
  id: string;
  kind: SearchSourceRef['kind'];
  scope: MemoryScope;
  text: string;
}

export type SearchQualitySourceId = (typeof SEARCH_QUALITY_SOURCES)[number]['id'];
export type SearchQualityTag =
  | 'cjk'
  | 'english'
  | 'mixed'
  | 'identifier'
  | 'short-cjk'
  | 'cross-language'
  | 'zero-lexical'
  | 'negative'
  | 'scope-conflict'
  | 'multi-source';

export interface SearchQualityCase {
  id: string;
  split: 'calibration' | 'holdout';
  query: string;
  scope: SearchScope;
  expectedSourceIds: readonly SearchQualitySourceId[];
  tags: readonly SearchQualityTag[];
  forbiddenSourceIds?: readonly SearchQualitySourceId[];
}

export const SEARCH_QUALITY_WORKSPACES = {
  aurora: 'quality-workspace-aurora',
  orchard: 'quality-workspace-orchard',
} as const;

